messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Low Poly Treadmill</title>
    <style>
        body { margin: 0; overflow: hidden; background: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// --- Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x202025);
scene.fog = new THREE.Fog(0x202025, 8, 20);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 2, 7);
camera.lookAt(0, 1.2, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(3, 5, 4);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0xffaa00, 0.3, 10);
pointLight.position.set(-2, 3, 2);
scene.add(pointLight);

// --- Materials ---
const bodyMat = new THREE.MeshStandardMaterial({ color: 0x4488cc, roughness: 0.7, flatShading: true });
const skinMat = new THREE.MeshStandardMaterial({ color: 0xddbb99, roughness: 0.7, flatShading: true });
const shoeMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.9, flatShading: true });
const beltMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.5, flatShading: true });

// --- Treadmill ---
function buildTreadmill() {
    const group = new THREE.Group();

    // Base/Frame
    const baseGeo = new THREE.BoxGeometry(2.4, 0.15, 1.2);
    const baseMesh = new THREE.Mesh(baseGeo, new THREE.MeshStandardMaterial({ color: 0x555555, flatShading: true }));
    baseMesh.position.y = 0.075;
    baseMesh.castShadow = true;
    baseMesh.receiveShadow = true;
    group.add(baseMesh);

    // Belt
    const beltGeo = new THREE.BoxGeometry(2.0, 0.05, 0.8);
    const beltMat2 = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.4 });
    const belt = new THREE.Mesh(beltGeo, beltMat2);
    belt.position.y = 0.175;
    group.add(belt);

    // Side rails
    for (let side of [-1, 1]) {
        const railGeo = new THREE.BoxGeometry(0.08, 0.5, 1.3);
        const rail = new THREE.Mesh(railGeo, new THREE.MeshStandardMaterial({ color: 0x666666, flatShading: true }));
        rail.position.set(side * 1.2, 0.4, 0);
        rail.castShadow = true;
        group.add(rail);
    }

    // Front/side posts
    for (let x of [-1, 1]) {
        for (let z of [-1, 1]) {
            const postGeo = new THREE.BoxGeometry(0.06, 1.5, 0.06);
            const post = new THREE.Mesh(postGeo, new THREE.MeshStandardMaterial({ color: 0x777777, flatShading: true }));
            post.position.set(x * 1.15, 0.75, z * 0.55);
            post.castShadow = true;
            group.add(post);
        }
    }

    // Handlebars
    for (let x of [-1, 1]) {
        const handleGeo = new THREE.BoxGeometry(0.06, 0.06, 0.5);
        const handle = new THREE.Mesh(handleGeo, new THREE.MeshStandardMaterial({ color: 0x888888, flatShading: true }));
        handle.position.set(x * 1.15, 1.45, 0);
        group.add(handle);
    }

    // Wheels (decorative)
    for (let x of [-1, 1]) {
        const wheelGeo = new THREE.CylinderGeometry(0.1, 0.1, 0.06, 6);
        const wheel = new THREE.Mesh(wheelGeo, new THREE.MeshStandardMaterial({ color: 0x444444, flatShading: true }));
        wheel.position.set(x * 0.9, 0.1, 0.65);
        wheel.rotation.x = Math.PI / 2;
        group.add(wheel);
    }

    return group;
}

const treadmill = buildTreadmill();
scene.add(treadmill);

// --- Ground plane ---
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x333338, roughness: 0.95 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
ground.receiveShadow = true;
scene.add(ground);

// --- Humanoid Figure ---
function buildHumanoid() {
    const human = new THREE.Group();

    // Helper to make a limb with pivot at the joint
    function makeLimb(length, width, mat, pos, rot) {
        const geo = new THREE.BoxGeometry(width, length, width * 0.8);
        const mesh = new THREE.Mesh(geo, mat);
        mesh.position.set(0, -length / 2, 0);
        mesh.castShadow = true;
        if (rot) mesh.rotation.set(rot.x || 0, rot.y || 0, rot.z || 0);
        return mesh;
    }

    // --- Torso ---
    const torso = new THREE.Group();
    torso.position.y = 1.45;

    const torsoGeo = new THREE.BoxGeometry(0.55, 0.7, 0.3);
    const torsoMesh = new THREE.Mesh(torsoGeo, bodyMat);
    torsoMesh.castShadow = true;
    torso.add(torsoMesh);

    // Belt
    const beltGeo = new THREE.BoxGeometry(0.57, 0.1, 0.32);
    const beltMesh = new THREE.Mesh(beltGeo, beltMat);
    beltMesh.position.y = -0.3;
    torso.add(beltMesh);

    human.add(torso);

    // --- Head ---
    const head = new THREE.Group();
    head.position.y = 0.52;

    const headGeo = new THREE.BoxGeometry(0.32, 0.35, 0.32);
    const headMesh = new THREE.Mesh(headGeo, skinMat);
    headMesh.castShadow = true;
    head.add(headMesh);

    // Neck
    const neckGeo = new THREE.BoxGeometry(0.15, 0.12, 0.15);
    const neckMesh = new THREE.Mesh(neckGeo, skinMat);
    neckMesh.position.y = -0.22;
    head.add(neckMesh);

    torso.add(head);

    // --- Left Arm ---
    const lShoulder = new THREE.Group();
    lShoulder.position.set(-0.35, 0.25, 0);

    const lArmGeo = new THREE.BoxGeometry(0.12, 0.35, 0.12);
    const lArmMesh = new THREE.Mesh(lArmGeo, bodyMat);
    lArmMesh.position.y = -0.175;
    lShoulder.add(lArmMesh);

    const lForearm = new THREE.Group();
    lForearm.position.y = -0.35;

    const lForearmGeo = new THREE.BoxGeometry(0.11, 0.32, 0.11);
    const lForearmMesh = new THREE.Mesh(lForearmGeo, skinMat);
    lForearmMesh.position.y = -0.16;
    lForearm.add(lForearmMesh);

    // Hand
    const lHandGeo = new THREE.BoxGeometry(0.1, 0.08, 0.1);
    const lHandMesh = new THREE.Mesh(lHandGeo, skinMat);
    lHandMesh.position.y = -0.34;
    lForearm.add(lHandMesh);

    lShoulder.add(lForearm);
    torso.add(lShoulder);

    // --- Right Arm ---
    const rShoulder = new THREE.Group();
    rShoulder.position.set(0.35, 0.25, 0);

    const rArmGeo = new THREE.BoxGeometry(0.12, 0.35, 0.12);
    const rArmMesh = new THREE.Mesh(rArmGeo, bodyMat);
    rArmMesh.position.y = -0.175;
    rShoulder.add(rArmMesh);

    const rForearm = new THREE.Group();
    rForearm.position.y = -0.35;

    const rForearmGeo = new THREE.BoxGeometry(0.11, 0.32, 0.11);
    const rForearmMesh = new THREE.Mesh(rForearmGeo, skinMat);
    rForearmMesh.position.y = -0.16;
    rForearm.add(rForearmMesh);

    const rHandGeo = new THREE.BoxGeometry(0.1, 0.08, 0.1);
    const rHandMesh = new THREE.Mesh(rHandGeo, skinMat);
    rHandMesh.position.y = -0.34;
    rForearm.add(rHandMesh);

    rShoulder.add(rForearm);
    torso.add(rShoulder);

    // --- Left Leg ---
    const lHip = new THREE.Group();
    lHip.position.set(-0.14, -0.38, 0);

    const lThighGeo = new THREE.BoxGeometry(0.16, 0.4, 0.16);
    const lThighMesh = new THREE.Mesh(lThighGeo, bodyMat);
    lThighMesh.position.y = -0.2;
    lHip.add(lThighMesh);

    const lShin = new THREE.Group();
    lShin.position.y = -0.4;

    const lShinGeo = new THREE.BoxGeometry(0.14, 0.38, 0.14);
    const lShinMesh = new THREE.Mesh(lShinGeo, bodyMat);
    lShinMesh.position.y = -0.19;
    lShin.add(lShinMesh);

    // Shoe
    const lShoeGeo = new THREE.BoxGeometry(0.14, 0.08, 0.22);
    const lShoeMesh = new THREE.Mesh(lShoeGeo, shoeMat);
    lShoeMesh.position.set(0, -0.4, 0.03);
    lShin.add(lShoeMesh);

    lHip.add(lShin);
    torso.add(lHip);

    // --- Right Leg ---
    const rHip = new THREE.Group();
    rHip.position.set(0.14, -0.38, 0);

    const rThighGeo = new THREE.BoxGeometry(0.16, 0.4, 0.16);
    const rThighMesh = new THREE.Mesh(rThighGeo, bodyMat);
    rThighMesh.position.y = -0.2;
    rHip.add(rThighMesh);

    const rShin = new THREE.Group();
    rShin.position.y = -0.4;

    const rShinGeo = new THREE.BoxGeometry(0.14, 0.38, 0.14);
    const rShinMesh = new THREE.Mesh(rShinGeo, bodyMat);
    rShinMesh.position.y = -0.19;
    rShin.add(rShinMesh);

    const rShoeGeo = new THREE.BoxGeometry(0.14, 0.08, 0.22);
    const rShoeMesh = new THREE.Mesh(rShoeGeo, shoeMat);
    rShoeMesh.position.set(0, -0.4, 0.03);
    rShin.add(rShoeMesh);

    rHip.add(rShin);
    torso.add(rHip);

    return { human, torso, head, lShoulder, lForearm, rShoulder, rForearm, lHip, lShin, rHip, rShin };
}

const human = buildHumanoid();
human.position.set(0, 0.17, 0);
scene.add(human);

// --- Animation State ---
const CYCLE_DURATION = 10; // seconds
const STAND1_DURATION = 2;
const WALK_DURATION = 3;
const RUN_DURATION = 3;
const STAND2_DURATION = 2;

let startTime = null;

// --- Animation Parameters ---
function getPhase(t) {
    const cycleT = t % CYCLE_DURATION;
    if (cycleT < STAND1_DURATION) return { name: 'stand1', t: cycleT };
    if (cycleT < STAND1_DURATION + WALK_DURATION) return { name: 'walk', t: cycleT - STAND1_DURATION };
    if (cycleT < STAND1_DURATION + WALK_DURATION + RUN_DURATION) return { name: 'run', t: cycleT - STAND1_DURATION - WALK_DURATION };
    return { name: 'stand2', t: cycleT - STAND1_DURATION - WALK_DURATION - RUN_DURATION };
}

function lerp(a, b, t) { return a + (b - a) * t; }
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }

function animateHuman(phase, dt) {
    const { human, torso, head, lShoulder, lForearm, rShoulder, rForearm, lHip, lShin, rHip, rShin } = human;

    // Default idle sway
    const idleSway = Math.sin(performance.now() * 0.001) * 0.01;

    switch (phase.name) {
        case 'stand1':
        case 'stand2': {
            // Stand still with subtle idle sway
            torso.rotation.x = 0;
            head.rotation.x = 0;

            // Arms hang naturally
            lShoulder.rotation.x = 0.05;
            lForearm.rotation.x = -0.05;
            rShoulder.rotation.x = -0.05;
            rForearm.rotation.x = 0.05;

            // Legs straight
            lHip.rotation.x = 0;
            lShin.rotation.x = 0;
            rHip.rotation.x = 0;
            rShin.rotation.x = 0;

            human.position.y = lerp(human.position.y, 0.17, 0.05);
            human.rotation.y = lerp(human.rotation.y, 0, 0.05);
            break;
        }

        case 'walk': {
            const walkSpeed = 1.5; // radians per second
            const t = phase.t * walkSpeed;

            // Walking rhythm
            const lArmSwing = Math.sin(t) * 0.5;
            const rArmSwing = Math.sin(t + Math.PI) * 0.5;
            const lLegSwing = Math.sin(t + Math.PI) * 0.45;
            const rLegSwing = Math.sin(t) * 0.45;

            // Arms: moderate swing, slight forward bend
            lShoulder.rotation.x = lArmSwing * 0.6;
            lForearm.rotation.x = -Math.abs(lArmSwing) * 0.3;
            rShoulder.rotation.x = rArmSwing * 0.6;
            rForearm.rotation.x = -Math.abs(rArmSwing) * 0.3;

            // Legs: moderate swing, knee bends
            lHip.rotation.x = lLegSwing;
            lShin.rotation.x = clamp(lLegSwing * 0.8, 0, 0.5);
            rHip.rotation.x = rLegSwing;
            rShin.rotation.x = clamp(rLegSwing * 0.8, 0, 0.5);

            // Slight body bob
            human.position.y = 0.17 + Math.abs(Math.sin(t)) * 0.02;

            // Very slight forward lean
            torso.rotation.x = lerp(torso.rotation.x, 0.08, 0.05);
            head.rotation.x = lerp(head.rotation.x, -0.05, 0.05);
            human.rotation.y = lerp(human.rotation.y, 0.02, 0.05);
            break;
        }

        case 'run': {
            const runSpeed = 3.5; // radians per second
            const t = phase.t * runSpeed;

            // Running rhythm: larger, faster swings
            const lArmSwing = Math.sin(t) * 0.9;
            const rArmSwing = Math.sin(t + Math.PI) * 0.9;
            const lLegSwing = Math.sin(t + Math.PI) * 0.75;
            const rLegSwing = Math.sin(t) * 0.75;

            // Arms: large swing, significant forward bend, hands near chest
            lShoulder.rotation.x = lArmSwing * 0.8;
            lForearm.rotation.x = -0.6 - Math.abs(lArmSwing) * 0.4;
            rShoulder.rotation.x = rArmSwing * 0.8;
            rForearm.rotation.x = -0.6 - Math.abs(rArmSwing) * 0.4;

            // Legs: large swing, deep knee bends
            lHip.rotation.x = lLegSwing;
            lShin.rotation.x = clamp(lLegSwing * 1.2 + 0.3, 0, 0.8);
            rHip.rotation.x = rLegSwing;
            rShin.rotation.x = clamp(rLegSwing * 1.2 + 0.3, 0, 0.8);

            // Bouncing
            human.position.y = 0.17 + Math.abs(Math.sin(t * 2)) * 0.04;

            // Noticeable forward lean
            torso.rotation.x = lerp(torso.rotation.x, 0.2, 0.05);
            head.rotation.x = lerp(head.rotation.x, -0.1, 0.05);
            human.rotation.y = lerp(human.rotation.y, 0.08, 0.05);
            break;
        }
    }
}

// --- Main Loop ---
function render(timestamp) {
    requestAnimationFrame(render);

    if (startTime === null) startTime = timestamp;
    const elapsed = (timestamp - startTime) / 1000;

    const phase = getPhase(elapsed);
    animateHuman(phase, 1/60);

    renderer.render(scene, camera);
}

requestAnimationFrame(render);

// --- Resize handler ---
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```
